1	using Managers;
2	using Net;
3	using UnityEngine;
4	
5	namespace Game
6	{
7	    /// <summary>
8	    /// Turns an inbound THROW into a real rock, follows it with the camera, and keeps
9	    /// idle phones updated with the live skip count.
10	    /// </summary>
11	    /// <remarks>
12	    /// Shares the throw origin and tuning with AimPreview on purpose: if the preview
13	    /// and the live throw ever drift onto different rigs, the arc stops predicting the
14	    /// thing it claims to predict. Scaffolding — replace with authored scene content
15	    /// once the real lake exists.
16	    /// </remarks>
17	    public class RockLauncher : MonoBehaviour
18	    {
19	        [SerializeField] private float cameraFollowSmoothing = 0.25f;
20	        [SerializeField] private float spectateBroadcastInterval = 0.25f;
21	
22	        private RelayClient _client;
23	        private AimPreview _preview;
24	        private RockController _active;
25	
26	        private Camera _camera;
27	        private Vector3 _cameraHome;
28	        private Quaternion _cameraHomeRotation;
29	        private Vector3 _cameraVelocity;
30	        private bool _returningHome;
31	        private float _nextSpectateTime;
32	
33	        public RockController ActiveRock => _active;
34	
35	        private void Update()
36	        {
37	            EnsureBound();
38	            FollowActiveRock();
39	            BroadcastLiveState();
40	        }
41	
42	        private void OnDestroy()
43	        {
44	            if (_client != null) _client.ThrowReceived -= OnThrow;
45	        }
46	
47	        private void EnsureBound()
48	        {
49	            if (_preview == null) _preview = FindFirstObjectByType<AimPreview>();
50	
51	            if (_camera == null)
52	            {
53	                _camera = Camera.main;
54	                if (_camera != null)
55	                {
56	                    // Captured after AimPreview has framed the shot, so "home" is the
57	                    // aiming view rather than the scene's default camera placement.
58	                    _cameraHome = _camera.transform.position;
59	                    _cameraHomeRotation = _camera.transform.rotation;
60	                }
61	            }
62	
63	            if (_client != null || !RelayClient.HasInstance) return;
64	
65	            _client = RelayClient.Instance;
66	            _client.ThrowReceived += OnThrow;
67	        }
68	
69	        private void OnThrow(ThrowMessage message)
70	        {
71	            // Only the player whose turn it is, and only while a match is running.
72	            // Both halves matter: a phone that never got a TURN update could otherwise
73	            // fling rocks into someone else's turn, and ActivePlayer is null outside the
74	            // Playing phase — so an "is it your turn" check alone would let anyone throw
75	            // across the lobby and the results screen.
76	            if (TurnManager.HasInstance)
77	            {
78	                var turns = TurnManager.Instance;
79	                if (turns.Phase != MatchPhase.Playing) return;
80	                if (message.playerId != turns.ActivePlayer) return;
81	            }
82	
83	            if (_preview == null)
84	            {
85	                Debug.LogWarning("[RockLauncher] No AimPreview in the scene — nothing to launch from.");
86	                return;
87	            }
88	
89	            if (_active != null && _active.IsFlying) return; // one rock at a time
90	
91	            var tuning = _preview.Tuning;
92	            var stats = RockStats.Default;
93	
94	            // Same forward the preview drew with — a live throw down a different axis
95	            // than the arc promised would make the preview a liar.
96	            var launch = SkipPhysics.CreateLaunch(
97	                _preview.ThrowOrigin.position, _preview.ThrowForward,
98	                message.power, message.timingQuality,
99	                message.aimDeg, message.attackAngleDeg, message.spinRate,
100	                stats, tuning);
101	
102	            _active = CreateRockObject();
103	            _active.Launch(launch, stats, tuning, message.playerId);
104	        }
105	
106	        private void FollowActiveRock()
107	        {
108	            if (_camera == null) return;
109	
110	            if (_active != null && _active.IsFlying)
111	            {
112	                // Trail behind and above so the skips read clearly from the couch.
113	                var target = _active.transform.position + new Vector3(-4f, 3.5f, -7f);
114	                _camera.transform.position = Vector3.SmoothDamp(
115	                    _camera.transform.position, target, ref _cameraVelocity, cameraFollowSmoothing);
116	                _camera.transform.rotation = Quaternion.Slerp(
117	                    _camera.transform.rotation,
118	                    Quaternion.LookRotation(_active.transform.position - _camera.transform.position),
119	                    Time.deltaTime * 5f);
120	
121	                _returningHome = true;
122	                return;
123	            }
124	
125	            // Parked. Deliberately touch nothing: both of the interpolations below
126	            // approach their target asymptotically and never actually arrive, so
127	            // running them every idle frame left the aiming camera permanently
128	            // creeping by a hair instead of sitting square on to the lake.
129	            if (!_returningHome) return;
130	
131	            _camera.transform.position = Vector3.SmoothDamp(
132	                _camera.transform.position, _cameraHome, ref _cameraVelocity, cameraFollowSmoothing * 2f);
133	            _camera.transform.rotation = Quaternion.Slerp(
134	                _camera.transform.rotation, _cameraHomeRotation, Time.deltaTime * 3f);
135	
136	            var settled = Vector3.Distance(_camera.transform.position, _cameraHome) < 0.02f &&
137	                          Quaternion.Angle(_camera.transform.rotation, _cameraHomeRotation) < 0.1f;
138	
139	            if (!settled) return;
140	
141	            // Snap the last hair exactly onto the authored pose, then stop.
142	            _camera.transform.SetPositionAndRotation(_cameraHome, _cameraHomeRotation);
143	            _cameraVelocity = Vector3.zero;
144	            _returningHome = false;
145	        }
146	
147	        private void BroadcastLiveState()
148	        {
149	            if (_active == null || !_active.IsFlying) return;
150	            if (Time.time < _nextSpectateTime) return;
151	
152	            _nextSpectateTime = Time.time + spectateBroadcastInterval;
153	
154	            if (TurnManager.HasInstance)
155	            {
156	                TurnManager.Instance.BroadcastSpectate(
157	                    _active.SkipCount, _active.Distance, RockStats.Default.DisplayName);
158	            }
159	        }
160	
161	        private static RockController CreateRockObject()
162	        {
163	            var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
164	            go.name = "Rock";
165	            Destroy(go.GetComponent<Collider>()); // the custom solver owns collision
166	            go.transform.localScale = new Vector3(0.45f, 0.08f, 0.45f);
167	
168	            var shader = Shader.Find("Sprites/Default") ?? Shader.Find("Unlit/Color") ?? Shader.Find("Standard");
169	            go.GetComponent<MeshRenderer>().material = new Material(shader) { color = new Color(0.85f, 0.87f, 0.95f) };
170	
171	            return go.AddComponent<RockController>();
172	        }
173	    }
174	}
