5	namespace Net
6	{
7	    /// <summary>
8	    /// Wire format shared with the relay and the controller web app.
9	    /// </summary>
10	    /// <remarks>
11	    /// Every inbound message is deliberately flat so Unity's built-in JsonUtility
12	    /// can parse it — no Newtonsoft dependency. JsonUtility needs public fields
13	    /// rather than properties, hence the field style throughout.
14	    ///
15	    /// Outbound SPECTATE carries a per-player score map, which JsonUtility cannot
16	    /// serialise, so that one is written by hand in BuildSpectateJson.
17	    /// </remarks>
18	    public static class MessageType
19	    {
20	        public const string CreateRoom = "CREATE_ROOM";
21	        public const string RoomCreated = "ROOM_CREATED";
22	        public const string PlayerJoined = "PLAYER_JOINED";
23	        public const string PlayerLeft = "PLAYER_LEFT";
24	        public const string Aim = "AIM";
25	        public const string Throw = "THROW";
26	        public const string Turn = "TURN";
27	        public const string Spectate = "SPECTATE";
28	        public const string Error = "ERROR";
29	        public const string RoomClosed = "ROOM_CLOSED";
30	    }
31	
32	    /// <summary>Peeked first to decide which concrete type to parse into.</summary>
33	    [Serializable]
34	    public class MessageEnvelope
35	    {
36	        public string type;
37	    }
38	
39	    [Serializable]
40	    public class RoomCreatedMessage
41	    {
42	        public string roomCode;
43	    }
