65	    /// <summary>
66	    /// Cosmetic aim frame, ~20Hz. Never authoritative — dropping these may only
67	    /// degrade the preview, never change a throw's outcome.
68	    /// </summary>
69	    [Serializable]
70	    public class AimMessage
71	    {
72	        public string playerId;
73	        public int seq;
74	        public float aimDeg;
75	        public float attackAngleDeg;
76	        public float rollDeg;
77	        public float windup;
78	    }
