80	    /// <summary>The authoritative throw. Exactly one per gesture.</summary>
81	    [Serializable]
82	    public class ThrowMessage
83	    {
84	        public string playerId;
85	        public float power;
86	        public float timingQuality;
87	        public float aimDeg;
88	        public float attackAngleDeg;
89	        public float rollDeg;
90	        public float spinRate;
91	
92	        // Diagnostics from the phone — useful on the debug HUD while tuning.
93	        public float peakAccel;
94	        public float releaseDelayMs;
95	        public int sampleCount;
96	
97	        /// <summary>
98	        /// Measured devicemotion rate on the sending phone. This is the number that
99	        /// turns "iOS feels wrong" into a comparison: the swing analysis assumes a
100	        /// 60Hz-class feed, and a device reporting at half that undersamples the peak.
101	        /// </summary>
102	        public int sampleHz;
103	
104	        public override string ToString() =>
105	            $"{playerId}: pow {power:F2} tim {timingQuality:F2} aim {aimDeg:F0}° " +
106	            $"atk {attackAngleDeg:F0}° spin {spinRate:F0} " +
107	            $"(peak {peakAccel:F1} m/s², {sampleCount} samples @ {sampleHz}Hz)";
108	    }
109	
110	    public static class OutboundMessages
111	    {
112	        /// <summary>Tell one phone whether it is their turn.</summary>
113	        public static string BuildTurn(string playerId, bool yourTurn) =>
114	            $"{{\"type\":\"{MessageType.Turn}\",\"targetPlayerId\":\"{Escape(playerId)}\"," +
115	            $"\"yourTurn\":{(yourTurn ? "true" : "false")}}}";
116	
117	        /// <summary>
118	        /// Broadcast match state to every phone. Hand-written because the score map
119	        /// is a dictionary, which JsonUtility cannot serialise.
120	        /// </summary>
121	        /// <param name="phase">LOBBY, PLAYING or RESULTS. Without it an idle phone cannot
122	        /// tell "waiting to start" from "final scores" and shows the wrong caption in two
123	        /// of the three phases.</param>
124	        public static string BuildSpectate(
125	            string activePlayer, string rockName, int liveSkips, float liveDistance,
126	            IReadOnlyDictionary<string, int> scores,
127	            string phase = "PLAYING", int round = 1, int totalRounds = 1)
128	        {
129	            var sb = new StringBuilder(288);
130	            sb.Append('{')
131	              .Append($"\"type\":\"{MessageType.Spectate}\",")
132	              .Append($"\"activePlayer\":\"{Escape(activePlayer)}\",")
133	              .Append($"\"rockName\":\"{Escape(rockName)}\",")
134	              .Append($"\"phase\":\"{Escape(phase)}\",")
135	              .Append($"\"round\":{round},")
136	              .Append($"\"totalRounds\":{totalRounds},")
137	              .Append($"\"liveSkips\":{liveSkips},")
138	              .Append($"\"liveDistance\":{liveDistance.ToString("F2", System.Globalization.CultureInfo.InvariantCulture)},")
139	              .Append("\"scores\":{");
140	
141	            if (scores != null)
142	            {
143	                var first = true;
144	                foreach (var pair in scores)
145	                {
146	                    if (!first) sb.Append(',');
147	                    sb.Append($"\"{Escape(pair.Key)}\":{pair.Value}");
148	                    first = false;
149	                }
150	            }
151	
152	            return sb.Append("}}").ToString();
153	        }
154	
155	        /// <summary>Minimal JSON string escaping — player names are user-supplied.</summary>
156	        private static string Escape(string value)
157	        {
158	            if (string.IsNullOrEmpty(value)) return string.Empty;
159	            return value.Replace("\\", "\\\\").Replace("\"", "\\\"")
160	                        .Replace("\n", "\\n").Replace("\r", "\\r").Replace("\t", "\\t");
161	        }
162	    }
163	}
