1	using System.Collections.Generic;
2	using UnityEngine;
3	
4	namespace Game
5	{
6	    /// <summary>Everything describing a rock mid-flight.</summary>
7	    public struct SkipState
8	    {
9	        public Vector3 Position;
10	        public Vector3 Velocity;
11	
12	        /// <summary>Face angle in degrees from horizontal. The variable that decides a bounce.</summary>
13	        public float AttitudeDeg;
14	
15	        /// <summary>Gyroscopic stability. Widens the angle tolerance while it lasts.</summary>
16	        public float Spin;
17	
18	        public int SkipCount;
19	        public bool Sunk;
20	    }
21	
22	    /// <summary>What one integration step did.</summary>
23	    public struct SkipStep
24	    {
25	        public SkipState State;
26	        public bool Bounced;
27	        public bool Sank;
28	        public float ImpactSpeed;
29	    }
30	
31	    /// <summary>
32	    /// Custom bounce solver. Deliberately not Unity rigidbodies: skipping needs exact
33	    /// per-bounce control over attitude and energy loss, and the aim preview needs to
34	    /// run the same maths headlessly to draw its arc.
35	    /// </summary>
36	    /// <remarks>
37	    /// PURE. Step takes state in and returns state out; it mutates nothing, touches no
38	    /// scene, and publishes no events.
39	    ///
40	    /// That last part is load-bearing. The aim preview runs Step hundreds of times per
41	    /// frame for a throw that has not happened. If Step published SkipOccurredEvent,
42	    /// the preview would score imaginary throws and the scoreboard would climb while a
43	    /// player merely aimed. RockController inspects the returned SkipStep and publishes
44	    /// — and only when driving a real throw. Audio, VFX and camera shake follow the
45	    /// same rule: observable effects belong to the caller, never in here.
46	    /// </remarks>
47	    public static class SkipPhysics
48	    {
49	        /// <summary>Build the initial state from a throw descriptor.</summary>
50	        public static SkipState CreateLaunch(
51	            Vector3 origin, Vector3 forward, float power, float timingQuality,
52	            float aimDeg, float attackAngleDeg, float spinRate,
53	            in RockStats stats, SkipTuning tuning)
54	        {
55	            // Poor timing costs speed rather than blocking the throw — a mistimed
56	            // release should feel weak, not broken.
57	            var speed = Mathf.Lerp(tuning.MinSpeed, tuning.MaxSpeed, Mathf.Clamp01(power))
58	                      * Mathf.Lerp(tuning.WorstTimingSpeedScale, 1f, Mathf.Clamp01(timingQuality));
59	
60	            var heading = Quaternion.AngleAxis(aimDeg, Vector3.up) * forward.normalized;
61	            var pitch = tuning.LaunchPitchDeg * Mathf.Deg2Rad;
62	
63	            var velocity = heading * (speed * Mathf.Cos(pitch)) + Vector3.up * (speed * Mathf.Sin(pitch));
64	
65	            return new SkipState
66	            {
67	                Position = origin,
68	                Velocity = velocity,
69	
70	                // Phone space -> physics space. attackAngleDeg is a delta from the
71	                // player's grip, so it is 0 when they hold naturally; the offset maps
72	                // that onto the angle a real stone wants. See SkipTuning for why.
73	                AttitudeDeg = attackAngleDeg + tuning.AttackAngleOffsetDeg,
74	                Spin = Mathf.Abs(spinRate),
75	                SkipCount = 0,
76	                Sunk = false,
77	            };
78	        }
79	
80	        /// <summary>Advance one fixed step. Pure — see the class remarks.</summary>
81	        public static SkipStep Step(in SkipState state, in RockStats stats, SkipTuning tuning, float dt)
82	        {
83	            var next = state;
84	            var result = new SkipStep();
85	
86	            if (next.Sunk)
87	            {
88	                result.State = next;
89	                return result;
90	            }
91	
92	            next.Velocity += Vector3.down * (tuning.Gravity * dt);
93	            next.Position += next.Velocity * dt;
94	
95	            var crossedSurface = next.Position.y <= tuning.WaterY && next.Velocity.y < 0f;
96	            if (!crossedSurface)
97	            {
98	                result.State = next;
99	                return result;
100	            }
101	
102	            next.Position.y = tuning.WaterY;
103	
104	            var speed = next.Velocity.magnitude;
105	            result.ImpactSpeed = speed;
106	
107	            // How steeply it is coming in, measured against the water plane.
108	            var horizontal = new Vector3(next.Velocity.x, 0f, next.Velocity.z);
109	            var incidenceDeg = horizontal.sqrMagnitude > 0.0001f
110	                ? Vector3.Angle(next.Velocity, horizontal)
111	                : 90f;
112	
113	            // Spin holds the stone's attitude steady, so it forgives a worse angle.
114	            var tolerance = stats.BaseToleranceDeg
115	                          + Mathf.Min(next.Spin * tuning.SpinToleranceScale, tuning.MaxSpinToleranceBonus);
116	
117	            var angleError = Mathf.Abs(next.AttitudeDeg - stats.OptimalAngleDeg);
118	
119	            var tooSlow = speed < stats.MinSkipSpeed;
120	            var tooSteep = incidenceDeg > tuning.MaxIncidenceDeg;
121	            var badAngle = angleError > tolerance;
122	
123	            if (tooSlow || tooSteep || badAngle)
124	            {
125	                next.Sunk = true;
126	                next.Velocity = Vector3.zero;
127	                result.Sank = true;
128	                result.State = next;
129	                return result;
130	            }
131	
132	            // Closer to the stone's optimal angle keeps more energy.
133	            var quality = 1f - Mathf.Clamp01(angleError / Mathf.Max(tolerance, 0.0001f));
134	            var restitution = stats.Restitution * Mathf.Lerp(tuning.WorstRestitution, tuning.BestRestitution, quality);
135	
136	            var velocity = next.Velocity;
137	            velocity.y = -velocity.y * restitution;
138	            velocity.x *= stats.Drag;
139	            velocity.z *= stats.Drag;
140	
141	            next.Velocity = velocity;
142	            next.Spin *= stats.SpinDecay;
143	            next.SkipCount++;
144	
145	            result.Bounced = true;
146	            result.State = next;
147	            return result;
148	        }
149	
150	        /// <summary>
151	        /// Run the throw forward and collect its path. Used by the aim preview, and by
152	        /// any tooling that wants a trajectory without spawning a rock.
153	        /// </summary>
154	        /// <param name="path">Filled with world positions. Cleared first; reuse the list to avoid per-frame garbage.</param>
155	        /// <returns>The final state, so callers can read SkipCount and distance.</returns>
156	        public static SkipState Predict(
157	            SkipState start, in RockStats stats, SkipTuning tuning,
158	            List<Vector3> path, int maxSteps = 0)
159	        {
160	            path.Clear();
161	            path.Add(start.Position);
162	
163	            var state = start;
164	            var steps = maxSteps > 0 ? maxSteps : tuning.MaxPredictSteps;
165	
166	            for (var i = 0; i < steps; i++)
167	            {
168	                var step = Step(state, stats, tuning, tuning.FixedStep);
169	                state = step.State;
170	                path.Add(state.Position);
171	
172	                if (state.Sunk) break;
173	            }
174	
175	            return state;
176	        }
177	    }
178	}
