5	    /// <summary>
6	    /// Global feel constants for skipping. Everything tunable lives here so the game
7	    /// can be dialled in from the inspector during play without recompiling.
8	    /// </summary>
9	    /// <remarks>
10	    /// Expect tuning to take longer than implementation. These starting values are
11	    /// educated guesses, not measurements — the ~20 degree optimum is the one number
12	    /// grounded in real stone-skipping physics.
13	    /// </remarks>
14	    [CreateAssetMenu(menuName = "RockSkipping/Skip Tuning", fileName = "SkipTuning")]
15	    public class SkipTuning : ScriptableObject
16	    {
17	        [Header("World")]
18	        public float Gravity = 9.81f;
19	        public float WaterY = 0f;
20	
21	        [Header("Launch")]
22	        [Tooltip("Speed at power = 0.")]
23	        public float MinSpeed = 6f;
24	        [Tooltip("Speed at power = 1.")]
25	        public float MaxSpeed = 26f;
26	        [Tooltip("Upward angle of the toss itself, separate from the stone's face angle.")]
27	        public float LaunchPitchDeg = 8f;
28	
29	        [Tooltip("Bridges phone space and physics space. The phone reports pitch as a delta " +
30	                 "from wherever the player gripped, so neutral is 0 — but a real stone wants " +
31	                 "about 20 degrees. Without this offset a natural, untilted throw is always " +
32	                 "outside tolerance and always sinks. Set to the stone's optimal angle so " +
33	                 "'hold naturally' means 'good throw', and tilting is how you trade it away.")]
34	        public float AttackAngleOffsetDeg = 20f;
35	        [Tooltip("Speed multiplier at zero timing quality. 1 would make timing irrelevant.")]
36	        [Range(0.1f, 1f)] public float WorstTimingSpeedScale = 0.6f;
37	
38	        [Header("Bounce")]
39	        [Tooltip("Steeper than this and the stone plows in instead of skipping.")]
40	        public float MaxIncidenceDeg = 45f;
41	        [Tooltip("Energy kept on a perfectly angled bounce.")]
42	        [Range(0f, 1f)] public float BestRestitution = 0.92f;
43	        [Tooltip("Energy kept on a bounce at the edge of tolerance.")]
44	        [Range(0f, 1f)] public float WorstRestitution = 0.45f;
45	
46	        [Header("Spin")]
47	        [Tooltip("Extra angle tolerance per unit of spin — gyroscopic stability.")]
48	        public float SpinToleranceScale = 0.02f;
49	        [Tooltip("Ceiling on that bonus, so a wild flick isn't an auto-win.")]
50	        public float MaxSpinToleranceBonus = 18f;
51	
52	        [Header("Simulation")]
53	        public float FixedStep = 0.02f;
54	        [Tooltip("Safety cap on prediction length.")]
55	        public int MaxPredictSteps = 500;
56	
57	        /// <summary>
58	        /// Runtime fallback so physics and the preview work before anyone authors an
59	        /// asset. Create a real SkipTuning asset once tuning starts in earnest.
60	        /// </summary>
61	        public static SkipTuning CreateDefault()
62	        {
63	            var tuning = CreateInstance<SkipTuning>();
64	            tuning.name = "SkipTuning (runtime default)";
65	            return tuning;
