1	using EventSystems;
2	using EventTypes.SkipEvents;
3	using UnityEngine;
4	
5	namespace Game
6	{
7	    /// <summary>
8	    /// One rock in flight. Drives the pure solver forward and turns its results into
9	    /// everything observable: movement, spin, and gameplay events.
10	    /// </summary>
11	    /// <remarks>
12	    /// This is the only place skip events are published. SkipPhysics.Step deliberately
13	    /// publishes nothing, because the aim preview runs it speculatively every frame for
14	    /// a throw that never happened — if the solver published, the preview would score
15	    /// imaginary throws. Keep every side effect on this side of the line.
16	    /// </remarks>
17	    public class RockController : MonoBehaviour
18	    {
19	        [SerializeField] private float visualSpinDegPerSec = 720f;
20	        [SerializeField] private float despawnDelay = 2.5f;
21	
22	        private SkipState _state;
23	        private RockStats _stats;
24	        private SkipTuning _tuning;
25	        private string _playerId;
26	        private Vector3 _origin;
27	        private float _accumulator;
28	        private float _visualSpin;
29	
30	        public bool IsFlying { get; private set; }
31	        public int SkipCount => _state.SkipCount;
32	        public float Distance => Vector3.Distance(_origin, _state.Position);
33	
34	        public void Launch(SkipState state, in RockStats stats, SkipTuning tuning, string playerId)
35	        {
36	            _state = state;
37	            _stats = stats;
38	            _tuning = tuning;
39	            _playerId = playerId;
40	            _origin = state.Position;
41	
42	            transform.position = state.Position;
43	            IsFlying = true;
44	        }
45	
46	        private void Update()
47	        {
48	            if (!IsFlying) return;
49	
50	            // Fixed-step accumulator so the simulation is frame-rate independent —
51	            // a bounce must not depend on where a frame boundary happened to land.
52	            _accumulator += Time.deltaTime;
53	
54	            var guard = 0;
55	            while (_accumulator >= _tuning.FixedStep && IsFlying && guard++ < 16)
56	            {
57	                _accumulator -= _tuning.FixedStep;
58	
59	                var step = SkipPhysics.Step(_state, _stats, _tuning, _tuning.FixedStep);
60	                _state = step.State;
61	
62	                if (step.Bounced)
63	                {
64	                    EventManager.Instance?.Publish(new SkipOccurredEvent(_state.SkipCount, step.ImpactSpeed));
65	                }
66	
67	                if (step.Sank)
68	                {
69	                    Finish();
70	                    break;
71	                }
72	            }
73	
74	            transform.position = _state.Position;
75	
76	            _visualSpin += visualSpinDegPerSec * Time.deltaTime;
77	            transform.rotation = Quaternion.Euler(-_state.AttitudeDeg, 0f, 0f) * Quaternion.Euler(0f, _visualSpin, 0f);
78	        }
79	
80	        private void Finish()
81	        {
82	            IsFlying = false;
83	
84	            EventManager.Instance?.Publish(
85	                new ThrowCompletedEvent(_playerId, _state.SkipCount, Distance));
86	
87	            Debug.Log($"[Rock] {_playerId}: {_state.SkipCount} skips over {Distance:F1} m");
88	            Destroy(gameObject, despawnDelay);
89	        }
90	    }
91	}
