1	using System.Collections.Generic;
2	using EventSystems;
3	using EventTypes.MatchEvents;
4	using EventTypes.SkipEvents;
5	using Net;
6	using Singleton;
7	using UnityEngine;
8	
9	namespace Managers
10	{
11	    /// <summary>Where the match is in its lifecycle. Drives what every screen shows.</summary>
12	    public enum MatchPhase
13	    {
14	        /// <summary>Players are joining. Nobody may throw yet.</summary>
15	        Lobby,
16	
17	        /// <summary>Turns are rotating. Exactly one player may throw at a time.</summary>
18	        Playing,
19	
20	        /// <summary>Final standings are up. Throws are refused until the next match.</summary>
21	        Results,
22	    }
23	
24	    /// <summary>
25	    /// Owns the player roster, whose turn it is, and where the match is in its lifecycle.
26	    /// The only thing that tells a phone to show its throw screen.
27	    /// </summary>
28	    /// <remarks>
29	    /// Publishes match events; deliberately computes no score — that lives solely in
30	    /// ScoreManager, so scoring can be retuned without touching turn logic.
31	    ///
32	    /// The match runs a fixed number of rounds, each giving every player one throw, and
33	    /// then ends. Before this existed turns rotated forever and the round counter was
34	    /// incremented but never read, so a session had no way to finish.
35	    /// </remarks>
36	    public class TurnManager : SingletonBase<TurnManager>
37	    {
38	        [Header("Match")]
39	        [Tooltip("Each round gives every player one throw.")]
40	        [SerializeField] private int roundsPerMatch = 3;
41	
42	        [Tooltip("Starts the match from the lobby, and starts the next one from the results screen.")]
43	        [SerializeField] private KeyCode startMatchKey = KeyCode.Space;
44	
45	        [Tooltip("Editor shortcut to hand the turn to the next player. Useful when a " +
46	                 "test client cannot throw for itself.")]
47	        [SerializeField] private KeyCode nextTurnKey = KeyCode.N;
48	
49	        private readonly List<string> _players = new();
50	        private readonly List<PlayerStanding> _standings = new();
51	        private int _current = -1;
52	        private int _round;
53	
54	        public MatchPhase Phase { get; private set; } = MatchPhase.Lobby;
55	
56	        /// <summary>Null outside the Playing phase — nobody may throw in a lobby.</summary>
57	        public string ActivePlayer =>
58	            Phase == MatchPhase.Playing && _current >= 0 && _current < _players.Count
59	                ? _players[_current]
60	                : null;
61	
62	        public IReadOnlyList<string> Players => _players;
63	        public int RoundsPerMatch => roundsPerMatch;
64	
65	        /// <summary>Zero-based index of the round in progress.</summary>
66	        public int CurrentRound => _round;
67	
68	        public bool CanStartMatch => Phase != MatchPhase.Playing && _players.Count > 0;
69	        public KeyCode StartMatchKey => startMatchKey;
70	
71	        protected override void Awake()
72	        {
73	            persistBetweenScenes = true;
74	            base.Awake();
75	
76	            EventManager.Instance?.Subscribe<PlayerJoinedEvent>(this, OnPlayerJoined);
77	            EventManager.Instance?.Subscribe<PlayerLeftEvent>(this, OnPlayerLeft);
78	            EventManager.Instance?.Subscribe<ThrowCompletedEvent>(this, _ => NextTurn());
79	        }
80	
81	        private void Update()
82	        {
83	            if (Input.GetKeyDown(startMatchKey) && CanStartMatch) StartMatch();
84	            if (Input.GetKeyDown(nextTurnKey) && Phase == MatchPhase.Playing) NextTurn();
85	        }
86	
87	        // ------------------------------------------------------------------ roster
88	
89	        private void OnPlayerJoined(PlayerJoinedEvent e)
90	        {
91	            if (!_players.Contains(e.PlayerId)) _players.Add(e.PlayerId);
92	            Debug.Log($"[TurnManager] {e.PlayerId} joined ({_players.Count} players)");
93	
94	            // Never auto-starts. A player walking in mid-lobby should not begin the match
95	            // for everyone else, and a late joiner mid-match just waits for their turn.
96	            SendTurnStates();
97	        }
98	
99	        private void OnPlayerLeft(PlayerLeftEvent e)
100	        {
101	            var index = _players.IndexOf(e.PlayerId);
102	            if (index < 0) return;
103	
104	            var wasActive = index == _current && Phase == MatchPhase.Playing;
105	            _players.RemoveAt(index);
106	
107	            if (_players.Count == 0)
108	            {
109	                // Nobody left to play for. Reset rather than stranding the match
110	                // mid-round with an empty roster.
111	                _current = -1;
112	                if (Phase != MatchPhase.Lobby) ReturnToLobby();
113	                return;
114	            }
115	
116	            // Removing someone before the active player shifts the index under it.
117	            if (index < _current) _current--;
118	
119	            if (wasActive) StartTurn(_current);
120	            else SendTurnStates();
121	        }
122	
123	        // ------------------------------------------------------------------ lifecycle
124	
125	        /// <summary>Begins a fresh match: scores cleared, round 0, first player up.</summary>
126	        public void StartMatch()
127	        {
128	            if (_players.Count == 0)
129	            {
130	                Debug.LogWarning("[TurnManager] Cannot start a match with no players.");
131	                return;
132	            }
133	
134	            ScoreManager.Instance?.ResetScores();
135	
136	            _round = 0;
137	            Phase = MatchPhase.Playing;
138	
139	            Debug.Log($"[TurnManager] Match started — {_players.Count} players, {roundsPerMatch} rounds");
140	            StartTurn(0);
141	        }
142	
143	        /// <summary>
144	        /// Advances to the next player, or ends the match if the last round is done.
145	        /// Called on ThrowCompletedEvent, so a sunk rock is what drives the match forward.
146	        /// </summary>
147	        public void NextTurn()
148	        {
149	            if (Phase != MatchPhase.Playing || _players.Count == 0) return;
150	
151	            if (_current + 1 >= _players.Count)
152	            {
153	                _round++;
154	                if (_round >= roundsPerMatch)
155	                {
156	                    EndMatch();
157	                    return;
158	                }
159	            }
160	
161	            StartTurn(_current + 1);
162	        }
163	
164	        private void EndMatch()
165	        {
166	            Phase = MatchPhase.Results;
167	            _current = -1;
168	
169	            RebuildStandings();
170	
171	            // A tie at the top has no single winner, and claiming one would be a lie the
172	            // results screen then has to render.
173	            var winner = _standings.Count > 0 &&
174	                         (_standings.Count == 1 || _standings[0].Score > _standings[1].Score)
175	                ? _standings[0].PlayerId
176	                : null;
177	
178	            Debug.Log($"[TurnManager] Match over after {_round} rounds — winner: {winner ?? "tied"}");
179	
180	            SendTurnStates();
181	            EventManager.Instance?.Publish(
182	                new MatchEndedEvent(_standings.ToArray(), winner, _round));
183	        }
184	
185	        /// <summary>Back to the join screen with scores cleared, ready for another match.</summary>
186	        public void ReturnToLobby()
187	        {
188	            Phase = MatchPhase.Lobby;
189	            _current = -1;
190	            _round = 0;
191	
192	            ScoreManager.Instance?.ResetScores();
193	            SendTurnStates();
194	
195	            Debug.Log("[TurnManager] Back in the lobby");
196	        }
197	
198	        private void StartTurn(int index)
199	        {
200	            if (_players.Count == 0)
201	            {
202	                _current = -1;
203	                return;
204	            }
205	
206	            // Positive modulo so a negative index wraps to the end rather than throwing.
207	            _current = ((index % _players.Count) + _players.Count) % _players.Count;
208	
209	            SendTurnStates();
210	            EventManager.Instance?.Publish(new TurnStartedEvent(ActivePlayer, _round));
211	            Debug.Log($"[TurnManager] Round {_round + 1}/{roundsPerMatch}: {ActivePlayer}'s turn");
212	        }
213	
214	        // ------------------------------------------------------------------ standings
215	
216	        /// <summary>
217	        /// Current standings, highest first. Rebuilt on demand rather than cached per
218	        /// frame — the results screen calls this once per Update, not once per OnGUI.
219	        /// </summary>
220	        public IReadOnlyList<PlayerStanding> RebuildStandings()
221	        {
222	            _standings.Clear();
223	
224	            var scores = ScoreManager.HasInstance ? ScoreManager.Instance : null;
225	            foreach (var player in _players)
226	            {
227	                _standings.Add(new PlayerStanding(player, scores?.GetScore(player) ?? 0));
228	            }
229	
230	            _standings.Sort((a, b) => b.Score.CompareTo(a.Score));
231	            return _standings;
232	        }
233	
234	        // ------------------------------------------------------------------ outbound
235	
236	        /// <summary>Every phone is told explicitly, so nobody is left on a stale screen.</summary>
237	        private void SendTurnStates()
238	        {
239	            var active = ActivePlayer;
240	            foreach (var player in _players)
241	            {
242	                RelayClient.Instance?.Send(OutboundMessages.BuildTurn(player, player == active));
243	            }
244	            BroadcastSpectate();
245	        }
246	
247	        /// <summary>Match state for the idle phones. Cheap enough to call on any change.</summary>
248	        public void BroadcastSpectate(int liveSkips = 0, float liveDistance = 0f, string rockName = "")
249	        {
250	            RelayClient.Instance?.Send(OutboundMessages.BuildSpectate(
251	                ActivePlayer ?? string.Empty, rockName, liveSkips, liveDistance,
252	                ScoreManager.Instance?.Scores,
253	                Phase.ToString().ToUpperInvariant(), _round + 1, roundsPerMatch));
254	        }
255	
256	        protected override void OnDestroy()
257	        {
258	            EventManager.Instance?.UnsubscribeFromAllEvents(this);
259	            base.OnDestroy();
260	        }
261	    }
262	}
