5	
6	namespace Managers
7	{
8	    /// <summary>
9	    /// First scene in the build order. Creates every manager that must outlive a
10	    /// scene transition, then hands off to the Lobby.
11	    /// </summary>
12	    public class Bootstrap : MonoBehaviour
13	    {
14	        [Tooltip("Scene to load once the persistent managers exist.")]
15	        [SerializeField] private string firstScene = SceneNames.Lobby;
16	
17	        [Tooltip("Advance to firstScene on boot. Off until the Lobby has real content — " +
18	                 "jumping straight into an empty scene just looks like the game closed.")]
19	        [SerializeField] private bool autoLoadFirstScene;
20	
21	        [Tooltip("Verbose EventManager logging. Turn on while wiring new events.")]
22	        [SerializeField] private bool eventDebugLogging;
23	
24	        [Tooltip("Start the relay and the public HTTPS tunnel automatically. Turn off only " +
25	                 "if you are running them yourself in a terminal.")]
26	        [SerializeField] private bool startLocalServices = true;
27	
28	        [Tooltip("TV screen showing the room code, join URL and QR. This is what guests read.")]
29	        [SerializeField] private bool showJoinScreen = true;
30	
31	        [Tooltip("Final standings when a match ends.")]
32	        [SerializeField] private bool showResultsScreen = true;
33	
34	        [Tooltip("On-screen relay/throw readout. M1 scaffolding; turn off for real play.")]
35	        [SerializeField] private bool showDebugHud = true;
36	
37	        [Tooltip("Live trajectory arc plus placeholder water. Scaffolding until the real lake scene exists.")]
38	        [SerializeField] private bool showAimPreview = true;
39	
40	        private void Awake()
41	        {
42	            EventManager.DebugLoggingEnabled = eventDebugLogging;
43	
44	            // Touching Instance is what creates each singleton. Every manager listed
45	            // here sets persistBetweenScenes = true in its own Awake, so each one
46	            // survives from here to Results.
47	            _ = EventManager.Instance;
48	
49	            // Before TurnManager, and that ordering is load-bearing. Both subscribe to
50	            // ThrowCompletedEvent, and EventManager delivers in subscription order — so
51	            // ScoreManager banks the final throw's points before TurnManager sees the
52	            // same event, ends the match and reads the standings. Created the other way
53	            // round, the winning throw would be missing from the results screen.
54	            _ = ScoreManager.Instance;
55	
56	            // Before RelayClient on purpose: this is what spawns the relay the client is
57	            // about to connect to. The client retries with backoff regardless, so the
58	            // order is not load-bearing — it just avoids a guaranteed first failure.
59	            if (startLocalServices) _ = Net.LocalServices.Instance;
60	
61	            // RelayClient must be created here, never per-scene: a scene-local socket
62	            // is torn down on every transition and every phone bounces back to the
63	            // join screen. That reads as a networking bug but is a lifecycle one.
64	            _ = Net.RelayClient.Instance;
65	
66	            // After RelayClient so it can subscribe before any phone joins, and after
67	            // ScoreManager for the delivery-order reason above.
68	            _ = TurnManager.Instance;
69	
70	            if (showJoinScreen) CreateJoinScreen();
71	            if (showResultsScreen) CreateResultsScreen();
72	            if (showDebugHud) CreateDebugHud();
73	            if (showAimPreview) CreateAimPreview();
74	        }
75	
76	        /// <summary>
77	        /// Persistent because the room code stays valid across every scene — a latecomer
78	        /// scanning during the Game scene must still be able to get in.
79	        /// </summary>
80	        private static void CreateJoinScreen()
81	        {
82	            if (FindFirstObjectByType<Ui.JoinScreen>() != null) return;
83	
84	            var screen = new GameObject("JoinScreen");
85	            screen.AddComponent<Ui.JoinScreen>();
86	            DontDestroyOnLoad(screen);
87	        }
88	
89	        /// <summary>Persistent for the same reason as the rest: it outlives any one scene.</summary>
90	        private static void CreateResultsScreen()
91	        {
92	            if (FindFirstObjectByType<Ui.ResultsScreen>() != null) return;
93	
94	            var screen = new GameObject("ResultsScreen");
95	            screen.AddComponent<Ui.ResultsScreen>();
96	            DontDestroyOnLoad(screen);
97	        }
98	
99	        private static void CreateAimPreview()
100	        {
101	            if (FindFirstObjectByType<Game.AimPreview>() != null) return;
102	
103	            var preview = new GameObject("AimPreview");
104	            preview.AddComponent<Game.AimPreview>();
105	
106	            // Same object so the launcher can share the preview's throw origin and
107	            // tuning — a live throw that used a different rig would make the arc lie.
108	            preview.AddComponent<Game.RockLauncher>();
