1	using System.Collections.Generic;
2	using System.Linq;
3	using UnityEngine;
4	
5	namespace Net
6	{
7	    /// <summary>
8	    /// On-screen readout of live aim and recent throws. This is the M1 acceptance
9	    /// instrument: it shows the spread across recent throws so "the same gesture
10	    /// twice lands within ~10%" can be read off the screen rather than guessed at.
11	    /// </summary>
12	    /// <remarks>
13	    /// Scaffolding, not shipping UI. Delete once AimPreview and the real HUD exist.
14	    /// OnGUI is used deliberately — it needs no Canvas setup and works in any scene.
15	    /// </remarks>
16	    public class RelayDebugHud : MonoBehaviour
17	    {
18	        [SerializeField] private bool visible = true;
19	        [SerializeField] private int historySize = 6;
20	        [SerializeField] private KeyCode toggleKey = KeyCode.F1;
21	
22	        private readonly List<ThrowMessage> _throws = new();
23	        private AimMessage _latestAim;
24	        private int _aimFrames;
25	        private float _aimRateWindowStart;
26	        private float _aimHz;
27	        private RelayClient _client;
28	        private Game.AimPreview _preview;
29	
30	        private void OnDestroy()
31	        {
32	            if (_client == null) return;
33	            _client.AimReceived -= OnAim;
34	            _client.ThrowReceived -= OnThrow;
35	        }
36	
37	        /// <summary>
38	        /// Binds whenever the client shows up, in either order. Checks HasInstance
39	        /// rather than touching Instance, because Instance would *create* a
40	        /// RelayClient — and a diagnostic that conjures the thing it is diagnosing
41	        /// would hide the very failure worth seeing.
42	        /// </summary>
43	        private void EnsureBound()
44	        {
45	            // Cached rather than looked up in OnGUI, which runs several times a frame.
46	            if (_preview == null) _preview = FindFirstObjectByType<Game.AimPreview>();
47	
48	            if (_client != null || !RelayClient.HasInstance) return;
49	
50	            _client = RelayClient.Instance;
51	            _client.AimReceived += OnAim;
52	            _client.ThrowReceived += OnThrow;
53	        }
54	
55	        private void Update()
56	        {
57	            if (Input.GetKeyDown(toggleKey)) visible = !visible;
58	            EnsureBound();
59	
60	            // Measured, not assumed: if this reads well under 20 the phone or the
61	            // network is dropping aim frames and the preview will look choppy.
62	            if (Time.time - _aimRateWindowStart >= 1f)
63	            {
64	                _aimHz = _aimFrames / (Time.time - _aimRateWindowStart);
65	                _aimFrames = 0;
66	                _aimRateWindowStart = Time.time;
67	            }
68	        }
69	
70	        private void OnAim(AimMessage aim)
71	        {
72	            _latestAim = aim;
73	            _aimFrames++;
74	        }
75	
76	        private void OnThrow(ThrowMessage thrown)
77	        {
78	            _throws.Insert(0, thrown);
79	            while (_throws.Count > historySize) _throws.RemoveAt(_throws.Count - 1);
80	            Debug.Log($"[Throw] {thrown}");
81	        }
82	
83	        /// <summary>Spread as a percentage of the mean — the repeatability number.</summary>
84	        private static string Spread(IEnumerable<float> values)
85	        {
86	            var list = values.ToList();
87	            if (list.Count < 2) return "n/a";
88	
89	            var mean = list.Average();
90	            if (Mathf.Abs(mean) < 0.0001f) return "n/a";
91	
92	            var spread = (list.Max() - list.Min()) / Mathf.Abs(mean) * 100f;
93	            return $"{spread:F0}%";
94	        }
