13	namespace Net
14	{
15	    /// <summary>How far along the one-click launch is. Drives what the TV shows.</summary>
16	    public enum ServiceState
17	    {
18	        Idle,
19	        InstallingDependencies,
20	        StartingRelay,
21	        OpeningTunnel,
22	        Ready,
23	        Failed,
24	    }
25	
26	    /// <summary>
27	    /// Brings up everything a phone needs in order to join, as a side effect of pressing
28	    /// Play: the relay process and a public HTTPS tunnel to it.
29	    /// </summary>
30	    /// <remarks>
31	    /// The point is that hosting a game is one action. Previously it was three terminals
32	    /// and a hand-copied URL, which is fine for the person who built it and a non-starter
33	    /// for a party.
34	    ///
35	    /// One tunnel is enough for both jobs because the relay serves the controller page
36	    /// from the same origin it accepts WebSockets on (see server.js). The page therefore
37	    /// arrives over HTTPS — which the motion sensors require — and upgrades to wss:// on
38	    /// the same host, so there is no mixed-content problem to fight.
39	    ///
40	    /// The host itself does NOT go through the tunnel. RelayClient connects to
41	    /// ws://localhost:3000 directly, because routing the PC's own traffic through
42	    /// Cloudflare and back would add a datacenter round trip to every aim frame for no
43	    /// benefit. Only the phones need the public address.
44	    /// </remarks>
45	    public class LocalServices : SingletonBase<LocalServices>
46	    {
47	        [Tooltip("Bring up the relay and tunnel on Play. Turn off if you run them yourself in a terminal.")]
48	        [SerializeField] private bool launchOnStart = true;
49	
50	        [Tooltip("Must match the port in RelayClient's relayUrl.")]
51	        [SerializeField] private int relayPort = 3000;
52	
53	        [Tooltip("Echo relay and tunnel output into the Unity console.")]
54	        [SerializeField] private bool verboseLogging;
55	
56	        [Header("Timeouts (seconds)")]
57	        [SerializeField] private float dependencyInstallTimeout = 180f;
58	        [SerializeField] private float relayStartTimeout = 30f;
59	        [SerializeField] private float tunnelStartTimeout = 60f;
60	
61	        public ServiceState State { get; private set; } = ServiceState.Idle;
62	
63	        /// <summary>Public HTTPS origin for the controller page. Null until the tunnel is up.</summary>
64	        public string PublicUrl { get; private set; }
65	
66	        /// <summary>One line for the TV describing what is happening right now.</summary>
67	        public string StatusMessage { get; private set; } = "Starting up…";
68	
69	        /// <summary>On failure, what the person standing at the PC should actually do about it.</summary>
70	        public string FailureHint { get; private set; }
71	
72	        public int RelayPort => relayPort;
73	
74	        public event Action<ServiceState> StateChanged;
75	
76	        private Process _relay;
77	        private Process _tunnel;
78	        private bool _ownsRelay;
79	        private ChildProcessGroup _group;
80	
81	        private readonly ConcurrentQueue<string> _output = new();
82	
83	        // cloudflared prints the assigned hostname inside a banner box on stderr; there
84	        // is no machine-readable channel for it on a quick tunnel, so it gets scraped.
85	        private static readonly Regex TunnelUrlPattern =
86	            new(@"https://[a-z0-9][a-z0-9\-]*\.trycloudflare\.com", RegexOptions.IgnoreCase);
87	
88	        private string HealthUrl => $"http://127.0.0.1:{relayPort}/health";
89	
90	        protected override void Awake()
91	        {
92	            persistBetweenScenes = true;
93	            base.Awake();
94	        }
95	
96	        private void Start()
97	        {
98	            if (!launchOnStart)
99	            {
100	                SetState(ServiceState.Idle, "Auto-launch off — start the relay and tunnel yourself.");
101	                return;
102	            }
103	
104	            _group = ChildProcessGroup.Create();
105	            StartCoroutine(LaunchSequence());
106	        }
107	
108	        private void Update()
109	        {
110	            // Process output arrives on threadpool threads; everything that touches Unity
111	            // or mutates state happens here instead.
112	            while (_output.TryDequeue(out var line))
113	            {
114	                if (verboseLogging) Debug.Log($"[LocalServices] {line}");
115	
116	                if (PublicUrl != null) continue;
117	
118	                var match = TunnelUrlPattern.Match(line);
119	                if (match.Success)
120	                {
121	                    PublicUrl = match.Value;
122	                    Debug.Log($"[LocalServices] Tunnel open at {PublicUrl}");
123	                }
124	            }
125	        }
126	
127	        /// <summary>The address a phone should open, with the room code pre-filled.</summary>
128	        public string JoinUrlFor(string roomCode)
129	        {
130	            if (string.IsNullOrEmpty(PublicUrl)) return null;
131	            return string.IsNullOrEmpty(roomCode) ? PublicUrl : $"{PublicUrl}/?room={roomCode}";
132	        }
133	
134	        // ------------------------------------------------------------------ sequence
135	
136	        private IEnumerator LaunchSequence()
137	        {
138	            var relayDir = ResolveRelayDirectory();
139	            if (relayDir == null)
140	            {
141	                Fail("Can't find the relay.",
142	                     "Expected a 'relay' folder next to Assets/. LocalServices resolves it " +
143	                     "relative to Application.dataPath.");
144	                yield break;
145	            }
146	
147	            yield return StartRelay(relayDir);
148	            if (State == ServiceState.Failed) yield break;
149	
150	            yield return StartTunnel();
151	        }
152	
153	        private IEnumerator StartRelay(string relayDir)
154	        {
155	            // Reuse a relay that is already listening rather than fighting it for the
156	            // port. This is what keeps `npm start` in a terminal a valid dev loop, and
157	            // it means a stale relay from a previous run is harmless rather than fatal.
158	            var alreadyRunning = false;
159	            yield return ProbeHealth(ok => alreadyRunning = ok);
160	
161	            if (alreadyRunning)
162	            {
163	                _ownsRelay = false;
164	                SetState(ServiceState.StartingRelay, "Using the relay already running.");
165	                Debug.Log($"[LocalServices] Relay already listening on :{relayPort} — reusing it.");
166	                yield break;
167	            }
168	
169	            if (!Directory.Exists(Path.Combine(relayDir, "node_modules")))
170	            {
171	                SetState(ServiceState.InstallingDependencies, "First run — installing relay dependencies…");
172	                yield return InstallDependencies(relayDir);
173	                if (State == ServiceState.Failed) yield break;
174	            }
175	
176	            SetState(ServiceState.StartingRelay, "Starting the relay…");
177	
178	            var node = ResolveExecutable("node", new[] { @"C:\Program Files\nodejs" });
179	            if (node == null)
180	            {
181	                Fail("Node.js not found.",
182	                     "Install Node 20 or newer from nodejs.org and relaunch. " +
183	                     "LocalServices searched PATH and C:\\Program Files\\nodejs.");
184	                yield break;
185	            }
186	
187	            _relay = Spawn(node, "server.js", relayDir);
188	            if (_relay == null)
189	            {
190	                Fail("Could not start the relay.", "See the console for the underlying error.");
191	                yield break;
192	            }
193	
194	            _ownsRelay = true;
195	
196	            var deadline = Time.realtimeSinceStartup + relayStartTimeout;
197	            var healthy = false;
198	
199	            while (!healthy && Time.realtimeSinceStartup < deadline)
200	            {
201	                if (_relay.HasExited)
202	                {
203	                    Fail($"The relay exited immediately (code {_relay.ExitCode}).",
204	                         $"Something else may be holding port {relayPort}. Check the console output.");
205	                    yield break;
206	                }
207	
208	                yield return ProbeHealth(ok => healthy = ok);
209	                if (!healthy) yield return new WaitForSecondsRealtime(0.25f);
210	            }
211	
212	            if (!healthy)
213	            {
214	                Fail("The relay never answered its health check.",
215	                     $"It started but nothing is responding on port {relayPort}.");
216	            }
217	        }
218	
219	        private IEnumerator StartTunnel()
220	        {
221	            SetState(ServiceState.OpeningTunnel, "Opening the public tunnel…");
222	
223	            var cloudflared = ResolveExecutable("cloudflared", new[]
224	            {
225	                @"C:\Program Files (x86)\cloudflared",
226	                @"C:\Program Files\cloudflared",
227	                // winget drops a shim here, which is on PATH only after a new sign-in.
228	                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
229	                             "Microsoft", "WinGet", "Links"),
230	            });
231	
232	            if (cloudflared == null)
233	            {
234	                Fail("cloudflared not found.",
235	                     "Install it with:  winget install Cloudflare.cloudflared\n" +
236	                     "Then relaunch. Players cannot join without an HTTPS address — phone " +
237	                     "motion sensors refuse to work on a plain http:// page.");
238	                yield break;
239	            }
240	
241	            // --no-autoupdate: an update mid-party would restart the tunnel and hand out
242	            // a different hostname, silently invalidating every QR code on screen.
243	            _tunnel = Spawn(cloudflared,
244	                            $"tunnel --no-autoupdate --url http://localhost:{relayPort}",
245	                            Path.GetDirectoryName(cloudflared));
246	
247	            if (_tunnel == null)
248	            {
249	                Fail("Could not start cloudflared.", "See the console for the underlying error.");
250	                yield break;
251	            }
252	
253	            var deadline = Time.realtimeSinceStartup + tunnelStartTimeout;
254	
255	            while (PublicUrl == null && Time.realtimeSinceStartup < deadline)
256	            {
257	                if (_tunnel.HasExited)
258	                {
259	                    Fail($"cloudflared exited before giving us a URL (code {_tunnel.ExitCode}).",
260	                         "Quick tunnels are rate limited — wait a minute and try again, or " +
261	                         "check your internet connection. Turn on Verbose Logging to see its output.");
262	                    yield break;
263	                }
264	
265	                yield return null;
266	            }
267	
268	            if (PublicUrl == null)
269	            {
270	                Fail("The tunnel did not come up in time.",
271	                     "cloudflared is running but never printed a trycloudflare.com address. " +
272	                     "Turn on Verbose Logging to see what it is saying.");
273	                yield break;
274	            }
275	
276	            SetState(ServiceState.Ready, "Ready — phones can join.");
277	        }
278	
279	        private IEnumerator InstallDependencies(string relayDir)
280	        {
281	            // npm is a .cmd shim on Windows, which CreateProcess cannot launch directly.
282	            var install = Spawn("cmd.exe", "/c npm install --no-audit --no-fund", relayDir);
283	            if (install == null)
284	            {
285	                Fail("Could not run npm install.", $"Run it yourself in {relayDir} and relaunch.");
286	                yield break;
287	            }
288	
289	            var deadline = Time.realtimeSinceStartup + dependencyInstallTimeout;
290	            while (!install.HasExited && Time.realtimeSinceStartup < deadline)
291	            {
292	                yield return new WaitForSecondsRealtime(0.25f);
293	            }
294	
295	            if (!install.HasExited)
296	            {
297	                TryKill(install);
298	                Fail("npm install timed out.", $"Run it yourself in {relayDir} and relaunch.");
299	                yield break;
300	            }
301	
302	            if (install.ExitCode != 0)
303	            {
304	                Fail($"npm install failed (exit code {install.ExitCode}).",
305	                     $"Run it yourself in {relayDir} to see why.");
306	            }
307	        }
308	
309	        /// <summary>Single GET against /health. Invokes the callback with the result either way.</summary>
310	        private IEnumerator ProbeHealth(Action<bool> onResult)
311	        {
312	            using var request = UnityWebRequest.Get(HealthUrl);
313	            request.timeout = 2;
314	            yield return request.SendWebRequest();
315	            onResult(request.result == UnityWebRequest.Result.Success);
316	        }
317	
318	        // ------------------------------------------------------------------ processes
319	
320	        private Process Spawn(string fileName, string arguments, string workingDirectory)
321	        {
322	            var info = new ProcessStartInfo
323	            {
324	                FileName = fileName,
325	                Arguments = arguments,
326	                WorkingDirectory = workingDirectory ?? Environment.CurrentDirectory,
327	                UseShellExecute = false,
328	                CreateNoWindow = true,
329	                RedirectStandardOutput = true,
330	                RedirectStandardError = true,
331	            };
332	
333	            try
334	            {
335	                var process = new Process { StartInfo = info, EnableRaisingEvents = true };
336	
337	                // Both streams are drained. A redirected stream that nobody reads fills
338	                // its pipe buffer and blocks the child permanently — cloudflared is
339	                // chatty enough to hit that within seconds.
340	                process.OutputDataReceived += (_, e) => { if (e.Data != null) _output.Enqueue(e.Data); };
341	                process.ErrorDataReceived += (_, e) => { if (e.Data != null) _output.Enqueue(e.Data); };
342	
343	                process.Start();
344	                process.BeginOutputReadLine();
345	                process.BeginErrorReadLine();
346	
347	                _group?.Adopt(process);
348	
349	                Debug.Log($"[LocalServices] Started {Path.GetFileName(fileName)} {arguments} (pid {process.Id})");
350	                return process;
351	            }
352	            catch (Exception e)
353	            {
354	                Debug.LogError($"[LocalServices] Failed to start {fileName}: {e.Message}");
355	                return null;
356	            }
357	        }
358	
359	        private static void TryKill(Process process)
360	        {
361	            if (process == null) return;
362	
363	            try
364	            {
365	                if (!process.HasExited) process.Kill();
366	                process.WaitForExit(2000);
367	            }
368	            catch (Exception e)
369	            {
370	                Debug.LogWarning($"[LocalServices] Could not stop pid: {e.Message}");
371	            }
372	            finally
373	            {
374	                process.Dispose();
375	            }
376	        }
377	
378	        private void Shutdown()
379	        {
380	            TryKill(_tunnel);
381	            _tunnel = null;
382	
383	            // A relay we merely borrowed belongs to whoever started it.
384	            if (_ownsRelay) TryKill(_relay);
385	            _relay = null;
386	
387	            // Closes the job object, which terminates anything the kills above missed.
388	            _group?.Dispose();
389	            _group = null;
390	        }
391	
392	        /// <summary>
393	        /// Must override rather than declare: SingletonBase.OnApplicationQuit is virtual
394	        /// and sets the flag that stops Instance resurrecting a destroyed singleton
395	        /// during teardown. A private method of the same name would hide it, Unity would
396	        /// deliver the message here only, and that flag would never be set.
397	        /// </summary>
398	        protected override void OnApplicationQuit()
399	        {
400	            base.OnApplicationQuit();
401	            Shutdown();
402	        }
403	
404	        protected override void OnDestroy()
405	        {
406	            Shutdown();
407	            base.OnDestroy();
408	        }
409	
410	        // ------------------------------------------------------------------ resolution
411	
412	        /// <summary>
413	        /// Locates the relay folder. Works out to the same expression in both cases:
414	        /// in the editor dataPath is &lt;project&gt;/Assets, and in a player build it is
415	        /// &lt;exe folder&gt;/&lt;Product&gt;_Data, so the parent is the right place both times.
416	        /// </summary>
417	        private static string ResolveRelayDirectory()
418	        {
419	            var candidate = Path.GetFullPath(Path.Combine(Application.dataPath, "..", "relay"));
420	            return File.Exists(Path.Combine(candidate, "server.js")) ? candidate : null;
421	        }
422	
423	        /// <summary>
424	        /// Finds an executable on PATH, then in a list of known install locations.
425	        /// The fallbacks matter: an installer that edits PATH does not change the
426	        /// environment of an already-running Unity, so a freshly installed tool is
427	        /// invisible until a restart that nobody realises they need.
428	        /// </summary>
429	        private static string ResolveExecutable(string name, IEnumerable<string> extraDirectories)
430	        {
431	            var extensions = Application.platform == RuntimePlatform.WindowsEditor ||
432	                             Application.platform == RuntimePlatform.WindowsPlayer
433	                ? new[] { ".exe", ".cmd", ".bat", "" }
434	                : new[] { "" };
435	
436	            var pathDirs = (Environment.GetEnvironmentVariable("PATH") ?? string.Empty)
437	                .Split(Path.PathSeparator);
438	
439	            foreach (var directory in JoinDirectories(pathDirs, extraDirectories))
440	            {
441	                if (string.IsNullOrWhiteSpace(directory)) continue;
442	
443	                foreach (var extension in extensions)
444	                {
445	                    string full;
446	                    try
447	                    {
448	                        full = Path.Combine(directory.Trim(), name + extension);
449	                    }
450	                    catch (ArgumentException)
451	                    {
452	                        break; // a malformed PATH entry; skip the whole directory
453	                    }
454	
455	                    if (File.Exists(full)) return full;
456	                }
457	            }
458	
459	            return null;
460	        }
461	
462	        private static IEnumerable<string> JoinDirectories(IEnumerable<string> first, IEnumerable<string> second)
463	        {
464	            foreach (var item in first) yield return item;
465	            if (second == null) yield break;
466	            foreach (var item in second) yield return item;
467	        }
468	
469	        // ------------------------------------------------------------------ state
470	
471	        private void SetState(ServiceState state, string message)
472	        {
473	            State = state;
474	            StatusMessage = message;
475	            StateChanged?.Invoke(state);
476	        }
477	
478	        private void Fail(string message, string hint)
479	        {
480	            FailureHint = hint;
481	            SetState(ServiceState.Failed, message);
482	            Debug.LogError($"[LocalServices] {message}\n{hint}");
483	        }
484	    }
