1	using System;
2	using System.Diagnostics;
3	using System.Runtime.InteropServices;
4	using Debug = UnityEngine.Debug;
5	
6	namespace Net
7	{
8	    /// <summary>
9	    /// Binds spawned child processes to the lifetime of this one, so the relay and the
10	    /// tunnel cannot outlive the game.
11	    /// </summary>
12	    /// <remarks>
13	    /// Killing a process on Windows does NOT kill its children. Without this, every
14	    /// crashed editor session, every "stop responding and force quit", and every domain
15	    /// reload at the wrong moment leaves an orphaned node.exe holding port 3000 and an
16	    /// orphaned cloudflared holding a tunnel. The next launch then finds the port taken
17	    /// and fails in a way that looks like a bug in the game.
18	    ///
19	    /// A job object with KILL_ON_JOB_CLOSE is the OS-level fix: when the last handle to
20	    /// the job closes — including when the process holding it dies for any reason,
21	    /// gracefully or not — Windows terminates every process in the job. That covers the
22	    /// crash case, which an OnApplicationQuit hook cannot.
23	    ///
24	    /// LocalServices still kills its children explicitly on the way out. This is the
25	    /// backstop for when there is no way out.
26	    /// </remarks>
27	    public sealed class ChildProcessGroup : IDisposable
28	    {
29	        private IntPtr _handle;
30	
31	        private static readonly bool IsWindows =
32	            RuntimeInformation.IsOSPlatform(OSPlatform.Windows);
33	
34	        public bool IsActive => _handle != IntPtr.Zero;
35	
36	        /// <summary>
37	        /// Creates the group, or returns a no-op instance where job objects are not
38	        /// available. Callers do not branch on platform; they just adopt and dispose.
39	        /// </summary>
40	        public static ChildProcessGroup Create()
41	        {
42	            var group = new ChildProcessGroup();
43	            if (!IsWindows) return group;
44	
45	            try
46	            {
47	                // Unnamed: the handle is the only reference, which is exactly the
48	                // lifetime we want it tied to.
49	                var handle = CreateJobObject(IntPtr.Zero, null);
50	                if (handle == IntPtr.Zero)
51	                {
52	                    Debug.LogWarning($"[ChildProcessGroup] CreateJobObject failed ({Marshal.GetLastWin32Error()}); " +
53	                                     "children will only be cleaned up on a graceful quit.");
54	                    return group;
55	                }
56	
57	                var limits = new JobObjectExtendedLimitInformation
58	                {
59	                    BasicLimitInformation = new JobObjectBasicLimitInformation
60	                    {
61	                        LimitFlags = JobObjectLimitKillOnJobClose,
62	                    },
63	                };
64	
65	                var size = Marshal.SizeOf(limits);
66	                var buffer = Marshal.AllocHGlobal(size);
67	
68	                try
69	                {
70	                    Marshal.StructureToPtr(limits, buffer, false);
71	                    if (!SetInformationJobObject(handle, JobObjectExtendedLimitInformationClass, buffer, (uint)size))
72	                    {
73	                        Debug.LogWarning($"[ChildProcessGroup] SetInformationJobObject failed ({Marshal.GetLastWin32Error()}); " +
74	                                         "the kill-on-close guarantee is not in effect.");
75	                        CloseHandle(handle);
76	                        return group;
77	                    }
78	                }
79	                finally
80	                {
81	                    Marshal.FreeHGlobal(buffer);
82	                }
83	
84	                group._handle = handle;
85	            }
86	            catch (DllNotFoundException)
87	            {
88	                // Not Windows after all, or a stripped runtime. Degrade to graceful-quit
89	                // cleanup rather than taking the launcher down with us.
90	            }
91	            catch (EntryPointNotFoundException)
92	            {
93	            }
94	
95	            return group;
96	        }
97	
98	        /// <summary>Adopts a started process. Safe to call on a process that has already exited.</summary>
99	        public void Adopt(Process process)
100	        {
101	            if (_handle == IntPtr.Zero || process == null) return;
102	
103	            try
104	            {
105	                if (process.HasExited) return;
106	                if (!AssignProcessToJobObject(_handle, process.Handle))
107	                {
108	                    Debug.LogWarning($"[ChildProcessGroup] Could not adopt pid {process.Id} " +
109	                                     $"({Marshal.GetLastWin32Error()}); it may outlive a crash.");
110	                }
111	            }
112	            catch (Exception e)
113	            {
114	                Debug.LogWarning($"[ChildProcessGroup] Adoption failed: {e.Message}");
115	            }
116	        }
117	
118	        /// <summary>Closing the last handle terminates every adopted process.</summary>
119	        public void Dispose()
120	        {
121	            if (_handle == IntPtr.Zero) return;
122	            CloseHandle(_handle);
123	            _handle = IntPtr.Zero;
124	        }
