1	using UnityEngine;
2	
3	namespace Singleton
4	{
5	    /// <summary>
6	    /// Generic singleton base class to ensure a single instance of a MonoBehaviour-derived class.
7	    /// The syntax for creating a new singleton is <c>ClassName : SingletonBase&lt;ClassName&gt;</c>.
8	    /// </summary>
9	    /// <remarks>
10	    /// Ported from FactoryTM. Unused <c>using</c> directives for FactoryTM-only namespaces
11	    /// (Managers, Placeables, Ui, Weapons, Nodes, EventTypes) were stripped — they do not
12	    /// exist in this project and would not compile.
13	    /// </remarks>
14	    public class SingletonBase<T> : MonoBehaviour where T : MonoBehaviour
15	    {
16	        private static T _instance;
17	        private static bool _isQuitting;
18	
19	        public static bool HasInstance => _instance != null;
20	
21	        public static T Instance
22	        {
23	            get
24	            {
25	                if (_isQuitting)
26	                {
27	                    // Hand back the instance if it still exists so late teardown can
28	                    // unsubscribe safely, but never resurrect a destroyed one.
29	                    return _instance;
30	                }
31	
32	                if (_instance == null)
33	                {
34	                    _instance = FindFirstObjectByType<T>();
35	
36	                    if (_instance == null)
37	                    {
38	                        var singletonObject = new GameObject(typeof(T).Name);
39	                        _instance = singletonObject.AddComponent<T>();
40	                    }
41	                }
42	
43	                return _instance;
44	            }
45	        }
46	
47	        [SerializeField] protected bool persistBetweenScenes = false;
48	        [SerializeField] protected bool detachFromParent = true;
49	
50	        protected virtual void Awake()
51	        {
52	            // Statics survive play sessions when Enter Play Mode has domain reload
53	            // disabled, which would leave _isQuitting stuck true from the last run
54	            // and make Instance permanently return null.
55	            _isQuitting = false;
56	
57	            if (_instance != null && _instance != this)
58	            {
59	                Destroy(gameObject);
60	                return;
61	            }
62	
63	            _instance = this as T;
64	
65	            // DontDestroyOnLoad only works on root objects, so detach first.
66	            if (detachFromParent && transform.parent != null)
67	            {
68	                transform.SetParent(null);
69	            }
70	
71	            if (persistBetweenScenes)
72	            {
73	                DontDestroyOnLoad(gameObject);
74	            }
75	        }
76	
77	        protected virtual void OnDestroy()
78	        {
79	            if (_instance == this)
80	            {
81	                _instance = null;
82	            }
83	        }
84	
85	        protected virtual void OnApplicationQuit()
86	        {
87	            _isQuitting = true;
88	        }
89	    }
90	}
