1	using System;
2	using System.Collections.Generic;
3	using Singleton;
4	using UnityEngine;
5	
6	namespace EventSystems
7	{
8	    /// <summary>
9	    /// Central publish/subscribe hub. Subscribers are held weakly, so a destroyed
10	    /// listener is dropped on the next publish even if it forgot to unsubscribe.
11	    /// </summary>
12	    /// <remarks>
13	    /// Ported from FactoryTM with four changes, all required by this project's
14	    /// multi-scene structure (Bootstrap -> Lobby -> Game -> Results):
15	    /// <list type="number">
16	    /// <item>persistBetweenScenes is now true, so the manager survives scene loads.</item>
17	    /// <item>Destroyed-subscriber detection accounts for Unity's fake-null semantics.</item>
18	    /// <item>OnDestroy calls base.OnDestroy so the singleton static is cleared.</item>
19	    /// <item>UnsubscribeFromAllEvents no longer uses reflection, and removes every
20	    /// matching subscription rather than only the first.</item>
21	    /// </list>
22	    /// The unused FactoryTM-only using directives were also stripped.
23	    /// </remarks>
24	    public class EventManager : SingletonBase<EventManager>
25	    {
26	        /// <summary>Set true while wiring new events; publish failures are otherwise quiet.</summary>
27	        public static bool DebugLoggingEnabled = false;
28	
29	        private readonly Dictionary<Type, List<EventSubscription>> _subscriptions = new();
30	        private readonly List<EventSubscription> _pendingRemovals = new();
31	        private bool _isPublishing;
32	
33	        protected override void Awake()
34	        {
35	            // Must be true. SingletonBase only calls DontDestroyOnLoad when this is
36	            // set, and the manager has to outlive every scene transition. Hardcoded
37	            // rather than left to the SerializeField because SingletonBase.Instance
38	            // can auto-create this component, and an auto-created instance never has
39	            // an inspector value applied.
40	            persistBetweenScenes = true;
41	            base.Awake();
42	        }
43	
44	        private class EventSubscription
45	        {
46	            public WeakReference TargetReference { get; set; }
47	            public Delegate Callback { get; set; }
48	            public bool MarkedForRemoval { get; set; }
49	        }
50	
51	        /// <summary>
52	        /// Listen for an event:
53	        /// <c>EventManager.Instance?.Subscribe&lt;SomeEvent&gt;(this, e =&gt; Handler(e.Value));</c>
54	        /// Always pair with <see cref="UnsubscribeFromAllEvents"/> in OnDestroy.
55	        /// </summary>
56	        public void Subscribe<T>(object target, Action<T> callback) where T : IEvent
57	        {
58	            var eventType = typeof(T);
59	
60	            if (!_subscriptions.TryGetValue(eventType, out var subscriptionList))
61	            {
62	                subscriptionList = new List<EventSubscription>();
63	                _subscriptions[eventType] = subscriptionList;
64	            }
65	
66	            subscriptionList.Add(new EventSubscription
67	            {
68	                TargetReference = new WeakReference(target),
69	                Callback = callback
70	            });
71	        }
72	
73	        public void Unsubscribe<T>(object target) where T : IEvent
74	        {
75	            if (!_subscriptions.TryGetValue(typeof(T), out var subscriptionList))
76	                return;
77	
78	            RemoveMatching(subscriptionList, target);
79	        }
80	
81	        /// <summary>
82	        /// Drops every subscription belonging to <paramref name="target"/>.
83	        /// Call from OnDestroy — mandatory with multiple scenes, since each transition
84	        /// destroys every subscriber in the outgoing scene.
85	        /// </summary>
86	        public void UnsubscribeFromAllEvents(object target)
87	        {
88	            foreach (var kvp in _subscriptions)
89	            {
90	                RemoveMatching(kvp.Value, target);
91	            }
92	        }
93	
94	        public void UnsubscribeAllTargets()
95	        {
96	            foreach (var target in GetAllSubscribedTargets())
97	            {
98	                UnsubscribeFromAllEvents(target);
99	            }
100	        }
101	
102	        /// <summary>
103	        /// Number of subscription records held for an event type, including any not yet
104	        /// pruned. Diagnostics only — used to assert that dead subscribers get dropped.
105	        /// </summary>
106	        public int GetSubscriptionCount<T>() where T : IEvent
107	        {
108	            return _subscriptions.TryGetValue(typeof(T), out var list) ? list.Count : 0;
109	        }
110	
111	        public IEnumerable<object> GetAllSubscribedTargets()
112	        {
113	            var targets = new HashSet<object>();
114	
115	            foreach (var subscriptionList in _subscriptions.Values)
116	            {
117	                foreach (var subscription in subscriptionList)
118	                {
119	                    var target = subscription.TargetReference.Target;
120	                    if (!IsDead(target))
121	                        targets.Add(target);
122	                }
123	            }
124	
125	            return targets;
126	        }
127	
128	        public void Publish<T>(T eventData) where T : IEvent
129	        {
130	            var eventType = typeof(T);
131	            if (DebugLoggingEnabled) Debug.Log($"EventManager: Attempting to publish event of type {eventType.Name}");
132	
133	            if (!_subscriptions.TryGetValue(eventType, out var subscriptionList))
134	            {
135	                if (DebugLoggingEnabled) Debug.Log($"EventManager: No subscriptions found for event type {eventType.Name}");
136	                return;
137	            }
138	
139	            if (DebugLoggingEnabled) Debug.Log($"EventManager: Found {subscriptionList.Count} subscriptions for {eventType.Name}");
140	            _isPublishing = true;
141	
142	            for (int i = subscriptionList.Count - 1; i >= 0; i--)
143	            {
144	                var subscription = subscriptionList[i];
145	
146	                if (subscription.MarkedForRemoval)
147	                    continue;
148	
149	                var target = subscription.TargetReference.Target;
150	
151	                if (IsDead(target))
152	                {
153	                    subscription.MarkedForRemoval = true;
154	                    _pendingRemovals.Add(subscription);
155	                    continue;
156	                }
157	
158	                try
159	                {
160	                    ((Action<T>)subscription.Callback).Invoke(eventData);
161	                }
162	                catch (Exception e)
163	                {
164	                    Debug.LogError($"Error publishing event {eventType.Name} on target {target.GetType().Name}: {e.Message}");
165	                }
166	            }
167	
168	            _isPublishing = false;
169	            CleanupPendingRemovals();
170	        }
171	
172	        /// <summary>
173	        /// True when a subscriber can no longer receive events.
174	        /// </summary>
175	        /// <remarks>
176	        /// The UnityEngine.Object branch is load-bearing. WeakReference.Target is typed
177	        /// object, so a plain <c>== null</c> is reference equality and bypasses Unity's
178	        /// overloaded <c>==</c> that reports destroyed objects as null. Without it,
179	        /// destroyed MonoBehaviours keep getting invoked and throw
180	        /// MissingReferenceException into the catch above on every single publish —
181	        /// which with multiple scenes happens on every transition.
182	        /// </remarks>
183	        private static bool IsDead(object target)
184	        {
185	            if (target == null) return true;
186	            return target is UnityEngine.Object unityObject && unityObject == null;
187	        }
188	
189	        private void RemoveMatching(List<EventSubscription> subscriptionList, object target)
190	        {
191	            for (int i = subscriptionList.Count - 1; i >= 0; i--)
192	            {
193	                var subscription = subscriptionList[i];
194	                if (subscription.TargetReference.Target != target)
195	                    continue;
196	
197	                if (_isPublishing)
198	                {
199	                    subscription.MarkedForRemoval = true;
200	                    _pendingRemovals.Add(subscription);
201	                }
202	                else
203	                {
204	                    subscriptionList.RemoveAt(i);
205	                }
206	            }
207	        }
208	
209	        private void CleanupPendingRemovals()
210	        {
211	            if (_pendingRemovals.Count == 0)
212	                return;
213	
214	            foreach (var subscription in _pendingRemovals)
215	            {
216	                foreach (var kvp in _subscriptions)
217	                {
218	                    kvp.Value.Remove(subscription);
219	                }
220	            }
221	
222	            _pendingRemovals.Clear();
223	        }
224	
225	        public void Clear()
226	        {
227	            _subscriptions.Clear();
228	            _pendingRemovals.Clear();
229	            _isPublishing = false;
230	        }
231	
232	        protected override void OnDestroy()
233	        {
234	            Clear();
235	            // Without this the SingletonBase static is never cleared, so a stale
236	            // reference survives teardown when domain reload is disabled.
237	            base.OnDestroy();
238	        }
239	    }
240	}
