1	/**
2	 * Sensor normalization for the phone controller.
3	 *
4	 * The whole point of this module is that Unity never sees a platform difference.
5	 * Raw DeviceMotion/DeviceOrientation values disagree between iOS and Android in
6	 * ways that produce wrong behaviour rather than errors, so everything is converted
7	 * here into device-agnostic values: gravity-removed linear acceleration, and
8	 * orientation expressed as a delta from a calibration reference.
9	 *
10	 * Pure math is exported separately from the browser wiring so it can be unit
11	 * tested in Node with no device — see test-sensors.js.
12	 *
13	 * TEST STATUS: verified on Android (Chrome). iOS branches are written from spec
14	 * and marked `UNVERIFIED (iOS)`; grep that tag when a device is available.
15	 */
16	
17	// ---------------------------------------------------------------------------
18	// Pure math — no browser APIs below this line until the MotionSource section.
19	// ---------------------------------------------------------------------------
20	
21	/**
22	 * Signed shortest distance from `reference` to `current`, in degrees, in (-180, 180].
23	 * Used so a throw that crosses the 0/360 wrap doesn't produce a ~360 degree jump.
24	 */
25	export function shortestAngleDelta(current, reference) {
26	  let delta = (current - reference) % 360;
27	  if (delta > 180) delta -= 360;
28	  if (delta <= -180) delta += 360;
29	  return delta;
30	}
31	
32	/** Rotate a vector's X/Y about the Z axis by `degrees` (counter-clockwise). */
33	export function rotateXY(x, y, degrees) {
34	  const radians = (degrees * Math.PI) / 180;
35	  const cos = Math.cos(radians);
36	  const sin = Math.sin(radians);
37	  return { x: x * cos - y * sin, y: x * sin + y * cos };
38	}
39	
40	export function magnitude(v) {
41	  return Math.hypot(v.x, v.y, v.z);
42	}
43	
44	/**
45	 * Minimum forward lean of the phone's pointing axis before its heading is trusted.
46	 * 0.35 is about 70 degrees of pitch either side of level.
47	 */
48	export const MIN_POINTING_CONFIDENCE = 0.35;
49	
50	/**
51	 * Rotation speed above which the fused orientation reading is not trusted at all.
52	 *
53	 * `deviceorientation` is sensor-fused and lags real motion by tens of milliseconds —
54	 * fine while aiming, useless mid-swing, which is precisely when accuracy matters.
55	 */
56	export const FAST_ROTATION_DEG_PER_SEC = 120;
57	
58	/** How hard a trusted orientation reading pulls the integrated heading, per update. */
59	export const HEADING_CORRECTION_GAIN = 0.15;
60	
61	/**
62	 * Rate of change of the pointing bearing, in deg/s, from the gyroscope.
63	 *
64	 * `rotationRate` arrives with `devicemotion` at the full sensor rate and is very close
65	 * to instantaneous, where `deviceorientation` is a fused estimate that both lags and
66	 * arrives on its own slower schedule. Integrating this is what lets a fast swing be
67	 * tracked at all: sampling the fused angle alone means the heading in every sample is
68	 * from tens of milliseconds ago, so the arc trails the phone and the release frame
69	 * reports where the player was pointing a moment before they let go.
70	 *
71	 * Derived from the Z-X'-Y'' Euler kinematics and checked numerically against a
72	 * finite-difference of the rotation matrix: exact to ~5e-7 deg/s across 600 poses up
73	 * to 500 deg/s. The 1/cos(beta) term is the same singularity `pointingHeading` guards
74	 * — the caller must not integrate through a near-vertical phone.
75	 *
76	 * @param rotationRate DeviceMotionEvent.rotationRate, deg/s (alpha about Z, beta about
77	 *                     X, gamma about Y)
78	 */
79	export function headingRateFromGyro(beta, gamma, rotationRate) {
80	  const b = (beta * Math.PI) / 180;
81	  const g = (gamma * Math.PI) / 180;
82	
83	  const cosBeta = Math.cos(b);
84	  if (Math.abs(cosBeta) < 1e-3) return 0;
85	
86	  return (rotationRate.beta * Math.sin(g) - rotationRate.alpha * Math.cos(g)) / cosBeta;
87	}
88	
89	/**
90	 * Compass-style bearing of the direction the top of the phone points, plus how much
91	 * to trust it.
92	 *
93	 * WHY NOT JUST USE `alpha`: alpha is the Euler yaw of a Z-X'-Y'' rotation, and it is
94	 * degenerate when the phone pitches toward vertical — exactly what a throwing swing
95	 * does. At beta = 89 the heading reads -30; at beta = 91 the same phone reads +150.
96	 * A two degree difference in pitch mid-swing flips the aim completely around, which
97	 * is why physically straight throws veered hard left or right at random.
98	 *
99	 * Instead this takes the device's +Y axis (out of the top of the phone, the end you
100	 * point at the screen), rotates it into world space, and projects it onto the ground.
101	 * Deriving it from the full rotation rather than one Euler angle is what removes the
102	 * singularity. `confidence` is the length of that projection, signed by whether the
103	 * phone points forward or backward — near zero means the phone is aimed at the sky or
104	 * the floor and its heading means nothing.
105	 *
106	 * gamma is deliberately absent: rolling the phone about its long axis cannot change
107	 * where its top points, so aim is immune to wrist roll for free.
108	 *
109	 * @returns {{headingDeg: number, confidence: number}} bearing, clockwise-positive
110	 */
111	export function pointingHeading(alpha, beta) {
112	  const a = (alpha * Math.PI) / 180;
113	  const b = (beta * Math.PI) / 180;
114	
115	  // Device +Y expressed in world coordinates (X east, Y north, Z up).
116	  const cosBeta = Math.cos(b);
117	  const east = -Math.sin(a) * cosBeta;
118	  const north = Math.cos(a) * cosBeta;
119	
120	  return {
121	    headingDeg: (Math.atan2(east, north) * 180) / Math.PI,
122	    confidence: cosBeta,
123	  };
124	}
125	
126	export function clamp(value, min, max) {
127	  return value < min ? min : value > max ? max : value;
128	}
129	
130	/** Map a value from one range to another, clamped to 0..1. */
131	export function normalize01(value, min, max) {
132	  if (max === min) return 0;
133	  return clamp((value - min) / (max - min), 0, 1);
134	}
135	
136	/**
137	 * Separates gravity from user motion.
138	 *
139	 * We cannot use `DeviceMotionEvent.acceleration` (which would already exclude
140	 * gravity) because iOS does not provide it — see readAcceleration below. So we
141	 * low-pass the gravity-inclusive signal to estimate the gravity vector, then
142	 * subtract it. A low K reacts fast but leaks motion into the gravity estimate;
143	 * a high K is stable but lags when the phone is re-oriented.
144	 */
145	export const REFERENCE_SAMPLE_INTERVAL_MS = 1000 / 60;
146	
147	export class GravityFilter {
148	  constructor(k = 0.8) {
149	    this.k = k;
150	    this.gravity = null;
151	
152	    // The configured k is a per-SAMPLE weight, which silently encodes a sample
153	    // rate. Convert it once into a time constant so the filter can hold the same
154	    // behaviour in wall-clock terms on a device that reports at a different rate.
155	    // Android Chrome runs ~60Hz; iOS Safari is commonly slower, which would
156	    // otherwise make the gravity estimate adapt at half the intended speed and
157	    // leak the swing into the estimate it is supposed to be subtracting.
158	    this.tauMs = k > 0 && k < 1
159	      ? -REFERENCE_SAMPLE_INTERVAL_MS / Math.log(k)
160	      : 0;
161	  }
162	
163	  /**
164	   * @param accel gravity-inclusive acceleration
165	   * @param dtMs time since the previous sample. Defaults to the 60Hz reference, so
166	   *             at 60Hz this is bit-for-bit the old behaviour.
167	   * @returns {{x:number,y:number,z:number}} linear acceleration, gravity removed
168	   */
169	  update(accel, dtMs = REFERENCE_SAMPLE_INTERVAL_MS) {
170	    if (this.gravity === null) {
171	      // Seed from the first sample. Starting at zero would report a full 9.8 m/s^2
172	      // of fake "user acceleration" on the first frame and spike the power reading.
173	      this.gravity = { x: accel.x, y: accel.y, z: accel.z };
174	    } else {
175	      const k = this.tauMs > 0
176	        ? Math.exp(-Math.max(dtMs, 0) / this.tauMs)
177	        : this.k;
178	
179	      this.gravity.x = k * this.gravity.x + (1 - k) * accel.x;
180	      this.gravity.y = k * this.gravity.y + (1 - k) * accel.y;
181	      this.gravity.z = k * this.gravity.z + (1 - k) * accel.z;
182	    }
183	
184	    return {
185	      x: accel.x - this.gravity.x,
186	      y: accel.y - this.gravity.y,
187	      z: accel.z - this.gravity.z,
188	    };
189	  }
190	
191	  reset() {
192	    this.gravity = null;
193	  }
194	}
195	
196	/**
197	 * Fixed-capacity ring buffer of recent samples. Sized to hold the whole swing so
198	 * the release analysis can look back over it, without allocating during a throw.
199	 */
200	export class RingBuffer {
201	  constructor(capacity) {
202	    this.capacity = capacity;
203	    this.items = new Array(capacity);
204	    this.length = 0;
205	    this._next = 0;
206	  }
207	
208	  push(item) {
209	    this.items[this._next] = item;
210	    this._next = (this._next + 1) % this.capacity;
211	    if (this.length < this.capacity) this.length++;
212	  }
213	
214	  /** Oldest-to-newest. */
215	  toArray() {
216	    const out = [];
217	    const start = this.length < this.capacity ? 0 : this._next;
218	    for (let i = 0; i < this.length; i++) {
219	      out.push(this.items[(start + i) % this.capacity]);
220	    }
221	    return out;
222	  }
223	
224	  clear() {
225	    this.length = 0;
226	    this._next = 0;
227	  }
228	}
