255	/**
256	 * UNVERIFIED (iOS): iOS 13+ requires an explicit permission grant for motion and
257	 * orientation, requested from inside a user gesture. Android has no such API at
258	 * all, so calling requestPermission unconditionally throws there — hence the
259	 * feature detection rather than a try/catch or a UA sniff.
260	 */
261	export async function requestMotionPermission() {
262	  const needsMotion = typeof DeviceMotionEvent?.requestPermission === 'function';
263	  const needsOrientation = typeof DeviceOrientationEvent?.requestPermission === 'function';
264	
265	  if (!needsMotion && !needsOrientation) {
266	    return { granted: true, prompted: false };
267	  }
268	
269	  try {
270	    const results = await Promise.all([
271	      needsMotion ? DeviceMotionEvent.requestPermission() : 'granted',
272	      needsOrientation ? DeviceOrientationEvent.requestPermission() : 'granted',
273	    ]);
274	    return { granted: results.every((r) => r === 'granted'), prompted: true };
275	  } catch (err) {
276	    return { granted: false, prompted: true, error: err?.message ?? String(err) };
277	  }
278	}
