285	const SAMPLE_HZ = 60;
286	const BUFFER_SECONDS = 1.5;
287	
288	/**
289	 * Streams normalized samples from the device's motion and orientation sensors.
290	 *
291	 * Orientation is always reported relative to a calibration reference captured on
292	 * grip, never as an absolute. That is what makes the output comparable across
293	 * platforms: iOS and Android disagree on absolute heading (different norths, and
294	 * they count in opposite directions), but a delta from a captured zero agrees.
295	 */
296	export class MotionSource {
297	  constructor({ gravityK = 0.8 } = {}) {
298	    this.gravityFilter = new GravityFilter(gravityK);
299	    this.buffer = new RingBuffer(Math.ceil(SAMPLE_HZ * BUFFER_SECONDS));
300	
301	    this.reference = null;
302	    this.latestOrientation = { alpha: 0, beta: 0, gamma: 0 };
303	    this.latest = null;
304	    this.running = false;
305	
306	    // Last heading the phone was pointing while it was still well-conditioned, and
307	    // the heading captured at calibration. Held rather than recomputed through the
308	    // steep middle of a swing, where the pointing direction is meaningless — see
309	    // pointingHeading. This is what makes "point at the screen and let go" work:
310	    // the aim comes from the pose you aimed in, not from wherever the phone happened
311	    // to be flailing at the instant of release.
312	    this.headingDeg = null;
313	    this.referenceHeading = null;
314	
315	    // Last gyro-derived turn rate, deg/s. Also decides how far the fused orientation
316	    // reading is allowed to pull the estimate — see _onOrientation.
317	    this.headingRateDegPerSec = 0;
318	
319	    // Measured, not assumed. The whole cross-platform question comes down to
320	    // whether the two devices are actually feeding us data at comparable rates,
321	    // and this is the number that answers it.
322	    this.sampleHz = 0;
323	    this._lastSampleT = 0;
324	    this._intervalMs = 0;
325	
326	    this._onMotion = this._onMotion.bind(this);
327	    this._onOrientation = this._onOrientation.bind(this);
328	  }
329	
330	  start() {
331	    if (this.running) return;
332	    window.addEventListener('devicemotion', this._onMotion);
333	    window.addEventListener('deviceorientation', this._onOrientation);
334	    this.running = true;
335	  }
336	
337	  stop() {
338	    if (!this.running) return;
339	    window.removeEventListener('devicemotion', this._onMotion);
340	    window.removeEventListener('deviceorientation', this._onOrientation);
341	    this.running = false;
342	  }
343	
344	  /**
345	   * Capture the current orientation as the zero reference. Called on grip, which
346	   * is what turns "point your phone at the lake and hold" into a calibration step
347	   * the player never notices they are performing.
348	   */
349	  calibrate() {
350	    this.reference = { ...this.latestOrientation };
351	    this.referenceHeading = this.headingDeg;
352	    this.gravityFilter.reset();
353	    this.buffer.clear();
354	  }
355	
356	  hasReference() {
357	    return this.reference !== null;
358	  }
359	
360	  _onOrientation(event) {
361	    // Only alpha/beta/gamma are read. webkitCompassHeading is deliberately ignored
362	    // even though iOS provides it: it is absolute and counts the opposite way from
363	    // Android's alpha, so using it would make aiming steer backwards on one
364	    // platform. Deltas from a calibrated reference sidestep that entirely.
365	    this.latestOrientation = {
366	      alpha: event.alpha ?? 0,
367	      beta: event.beta ?? 0,
368	      gamma: event.gamma ?? 0,
369	    };
370	
371	    // Only trust the heading while the phone is actually pointing somewhere on the
372	    // horizon. Through the steep part of a swing this keeps the last good value
373	    // instead of tracking a direction that flips 180 degrees over two degrees of tilt.
374	    const { headingDeg, confidence } = pointingHeading(
375	      this.latestOrientation.alpha, this.latestOrientation.beta);
376	
377	    if (confidence < MIN_POINTING_CONFIDENCE) return;
378	
379	    if (this.headingDeg === null) {
380	      this.headingDeg = headingDeg;
381	      return;
382	    }
383	
384	    // Correct rather than overwrite, and only in proportion to how slowly the phone is
385	    // turning. This reading is drift-free but lags; the integrated one is immediate but
386	    // drifts. Snapping to this mid-swing would hand the lag straight back — so while the
387	    // phone is whipping around the gyro is believed outright, and the fused value only
388	    // reasserts itself once things settle, which is when its lag costs nothing.
389	    const trust = clamp(
390	      1 - Math.abs(this.headingRateDegPerSec) / FAST_ROTATION_DEG_PER_SEC, 0, 1);
391	
392	    this.headingDeg += HEADING_CORRECTION_GAIN * trust *
393	      shortestAngleDelta(headingDeg, this.headingDeg);
394	  }
395	
396	  _onMotion(event) {
397	    const accel = readAcceleration(event);
398	    if (!accel) return;
399	
400	    const now = performance.now();
401	    const dtMs = this._lastSampleT > 0 ? now - this._lastSampleT : REFERENCE_SAMPLE_INTERVAL_MS;
402	    this._lastSampleT = now;
403	
404	    // Smoothed so one hitched frame does not swing the reported rate around.
405	    this._intervalMs = this._intervalMs > 0 ? this._intervalMs * 0.9 + dtMs * 0.1 : dtMs;
406	    this.sampleHz = this._intervalMs > 0 ? 1000 / this._intervalMs : 0;
407	
408	    const rotationRate = readRotationRate(event);
409	
410	    // Advance the heading by the gyro at the full sensor rate. This is the half of the
411	    // filter that makes a fast swing survive: orientation events arrive on their own,
412	    // slower schedule and are already stale when they do, so between them the heading
413	    // would otherwise sit frozen at a value from tens of milliseconds ago — and the
414	    // release frame would report exactly that stale angle.
415	    this.headingRateDegPerSec = headingRateFromGyro(
416	      this.latestOrientation.beta, this.latestOrientation.gamma, rotationRate);
417	
418	    const forwardLean = Math.cos((this.latestOrientation.beta * Math.PI) / 180);
419	    if (this.headingDeg !== null && forwardLean >= MIN_POINTING_CONFIDENCE) {
420	      this.headingDeg += this.headingRateDegPerSec * (dtMs / 1000);
421	    }
422	
423	    const linearRaw = this.gravityFilter.update(accel, dtMs);
424	
425	    // Keep axes stable if the device rotates. Portrait lock is requested elsewhere
426	    // but is best-effort — not all browsers honour it — so compensate regardless.
427	    const screenAngle = window.screen?.orientation?.angle ?? 0;
428	    const rotated = rotateXY(linearRaw.x, linearRaw.y, -screenAngle);
429	    const linear = { x: rotated.x, y: rotated.y, z: linearRaw.z };
430	
431	    const ref = this.reference ?? this.latestOrientation;
432	    const sample = {
433	      t: now,
434	      linear,
435	      power: magnitude(linear),
436	
437	      // Live, every sample, right through the swing. Aim is whatever the phone is
438	      // pointing at now — the throw is taken from the last sample before release, so
439	      // freezing this earlier would throw away the aim the player actually released
440	      // on. Zero until a confident heading exists, so an uncalibrated throw goes
441	      // straight rather than somewhere arbitrary.
442	      dYaw: this.headingDeg !== null && this.referenceHeading !== null
443	        ? shortestAngleDelta(this.headingDeg, this.referenceHeading)
444	        : 0,
445	
446	      dBeta: shortestAngleDelta(this.latestOrientation.beta, ref.beta),
447	      dGamma: shortestAngleDelta(this.latestOrientation.gamma, ref.gamma),
448	      rotationRate,
449	    };
450	
451	    this.latest = sample;
452	    this.buffer.push(sample);
453	  }
454	}
