100	
101	/** Android only — iOS support for navigator.vibrate is unreliable, so this is a bonus. */
102	function confirmThrow(descriptor) {
103	  if (descriptor && navigator.vibrate) navigator.vibrate(30);
104	  return descriptor;
105	}
106	
107	function bindGrip() {
108	  const start = (event) => {
109	    event.preventDefault(); // stop the tap turning into a scroll or a zoom
110	    thrower.grip();
111	  };
112	  const end = (event) => {
113	    event.preventDefault();
114	    confirmThrow(thrower.release());
115	  };
116	
117	  if (GESTURE === ThrowGesture.TAP) {
118	    // Bound to the press, not the lift. The press is the instant the player chose;
119	    // waiting for touchend would add however long their thumb takes to come back up
120	    // to a value the physics reads as the exact moment of release.
121	    const tap = (event) => {
122	      event.preventDefault();
123	      confirmThrow(thrower.tap());
124	    };
125	
126	    ui.gripBtn.addEventListener('touchstart', tap, { passive: false });
127	    ui.gripBtn.addEventListener('mousedown', tap);
128	
129	    // Deliberately no touchcancel handler: in tap mode the finger is not held, so a
130	    // cancelled touch is not the player abandoning the throw.
131	    return;
132	  }
133	
134	  ui.gripBtn.addEventListener('touchstart', start, { passive: false });
135	  ui.gripBtn.addEventListener('touchend', end, { passive: false });
136	  ui.gripBtn.addEventListener('touchcancel', () => thrower.cancel());
137	
138	  // Mouse fallback so the gesture can be exercised on a desktop browser.
139	  ui.gripBtn.addEventListener('mousedown', start);
140	  ui.gripBtn.addEventListener('mouseup', end);
