115	        private void BuildQrTexture(QrMatrix matrix)
116	        {
117	            if (matrix == null || matrix.rows == null || matrix.size <= 0)
118	                throw new InvalidOperationException("empty matrix");
119	
120	            var quiet = Mathf.Max(0, quietZoneModules);
121	            var dimension = matrix.size + quiet * 2;
122	
123	            if (_qr != null) Destroy(_qr);
124	            _qr = new Texture2D(dimension, dimension, TextureFormat.RGBA32, false)
125	            {
126	                filterMode = FilterMode.Point,   // nearest-neighbour keeps module edges hard
127	                wrapMode = TextureWrapMode.Clamp,
128	            };
129	
130	            var pixels = new Color32[dimension * dimension];
131	            var light = new Color32(255, 255, 255, 255);
132	            var dark = new Color32(0, 0, 0, 255);
133	
134	            for (var i = 0; i < pixels.Length; i++) pixels[i] = light;
135	
136	            for (var row = 0; row < matrix.size; row++)
137	            {
138	                var bits = matrix.rows[row];
139	
140	                for (var col = 0; col < matrix.size && col < bits.Length; col++)
141	                {
142	                    if (bits[col] != '1') continue;
143	
144	                    // Texture origin is bottom-left; the matrix is written top-down.
145	                    var y = dimension - 1 - (row + quiet);
146	                    pixels[y * dimension + col + quiet] = dark;
147	                }
148	            }
149	
150	            _qr.SetPixels32(pixels);
151	            _qr.Apply();
152	        }
